if(!$initial){http_response_code(404);?><!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Rastreamento</title><body style="font-family:system-ui;padding:32px"><h1>Rastreamento indisponível</h1><p>O link expirou ou a entrega não está mais disponível.</p></body></html><?php exit;}
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Seu pedido está a caminho</title><style>body{margin:0;background:#f5f7fb;font-family:system-ui;color:#172033}.wrap{max-width:760px;margin:auto;padding:18px}.card{background:#fff;border-radius:22px;padding:20px;box-shadow:0 10px 30px #0001;margin-bottom:14px}h1{margin:0 0 6px;font-size:26px}.muted{color:#667085}.status{display:inline-block;background:#e9f8ef;color:#087443;border-radius:999px;padding:7px 12px;font-weight:700}.map{width:100%;height:440px;border:0;border-radius:18px;background:#e9edf3}.pulse{width:10px;height:10px;border-radius:50%;background:#16a34a;display:inline-block;margin-right:7px}.row{display:flex;justify-content:space-between;gap:12px;align-items:center}@media(max-width:600px){.map{height:58vh}.wrap{padding:10px}}</style></head><body><div class="wrap"><div class="card"><span class="status"><span class="pulse"></span>Entrega em andamento</span><h1>Seu pedido está a caminho 🛵</h1><p class="muted">A posição é atualizada automaticamente enquanto o entregador estiver em rota.</p><div class="row"><strong id="state">Buscando localização…</strong><span class="muted" id="updated"></span></div></div><div class="card"><iframe id="map" class="map" title="Localização do entregador"></iframe></div><div class="card muted">Por privacidade, o rastreamento funciona somente durante a entrega e este link expira automaticamente.</div></div><script>const token=<?= json_encode($token) ?>;const map=document.getElementById('map'),state=document.getElementById('state'),updated=document.getElementById('updated');function draw(lat,lng){const d=.008,b=[lng-d,lat-d,lng+d,lat+d].join(',');map.src='https://www.openstreetmap.org/export/embed.html?bbox='+encodeURIComponent(b)+'&layer=mapnik&marker='+encodeURIComponent(lat+','+lng)}async function tick(){try{const r=await fetch('api-delivery-track.php?t='+encodeURIComponent(token),{cache:'no-store'}),j=await r.json();if(!j.ok)throw 0;const x=j.tracking;if(x.order_status==='completed'){state.textContent='Entrega concluída ✓';return}if(x.latitude!==null){draw(x.latitude,x.longitude);state.textContent='Entregador em rota';updated.textContent='Atualizado agora'}else state.textContent='Aguardando primeiro sinal do GPS…'}catch(e){state.textContent='Reconectando ao rastreamento…'}}tick();setInterval(tick,12000);</script></body></html>